def splice(blocks):
    """Вставляет цитатные абзацы сразу после абзаца, который начинается с якоря."""
    extra = qblocks()
    used = set()
    out = []
    for block in blocks:
        out.append(block)
        if block[0] != "p":
            continue
        text = block[1]
        for anchor, addition in extra:
            if anchor in used:
                continue
            if text.startswith(anchor):
                out.append(("p", addition))
                used.add(anchor)
                break
    return out, used


def missing_anchors(used):
    return [a for a, _ in qblocks() if a not in used]
